"""Compare the code generated from the design class diagrams with the application (Chapter 5).

design/generated/<package>/ is written by the generateCode tool of the Visual Paradigm MCP plugin from the
design class diagrams DCL01..DCL06 (python tools/vp/v5_design_build.py code). For every generated class the
check looks for the class of the same name in abc_shop/<package>/ and compares
  [1] the superclass / implemented interface,
  [2] every attribute (instance field of the generated __init__; a leading _ marks a private association end),
  [3] every operation with its parameter names.
usage: python design/check_code.py
"""
import ast
import os
import py_compile
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
GEN = os.path.join(HERE, "generated")
APP = os.path.join(os.path.dirname(HERE), "abc_shop")
PACKAGES = ["model", "dao", "service", "ai", "controller"]


def app_classes(package):
    """name -> ClassDef for every class in abc_shop/<package> (and its sub-packages)."""
    out = {}
    for d, _, files in os.walk(os.path.join(APP, package)):
        for f in files:
            if f.endswith(".py"):
                tree = ast.parse(open(os.path.join(d, f), encoding="utf-8").read())
                for n in tree.body:
                    if isinstance(n, ast.ClassDef):
                        out[n.name] = n
    return out


def members(cls, classes):
    """Fields and methods of an application class, inherited ones included."""
    fields, methods, params = set(), set(), {}
    for b in [ast.unparse(x).split(".")[-1] for x in cls.bases]:
        if b in classes:
            f, m, p = members(classes[b], classes)
            fields |= f
            methods |= m
            params.update(p)
    for st in cls.body:
        if isinstance(st, ast.AnnAssign) and isinstance(st.target, ast.Name):
            fields.add(st.target.id)
        elif isinstance(st, ast.FunctionDef):
            methods.add(st.name)
            params[st.name] = [a.arg for a in st.args.args if a.arg not in ("self", "cls")] + \
                ([st.args.vararg.arg] if st.args.vararg else [])
            if st.name == "__init__":
                for node in ast.walk(st):
                    if isinstance(node, ast.Attribute) and isinstance(node.value, ast.Name) and node.value.id == "self":
                        fields.add(node.attr)
    return fields, methods, params


def generated(package):
    out = {}
    for f in sorted(os.listdir(os.path.join(GEN, package))):
        if f.endswith(".py"):
            path = os.path.join(GEN, package, f)
            py_compile.compile(path, doraise=True)
            for n in ast.parse(open(path, encoding="utf-8").read()).body:
                if isinstance(n, ast.ClassDef):
                    out[n.name] = n
    return out


def main():
    total = problems = 0
    lines = []
    for package in PACKAGES:
        gen, app = generated(package), app_classes(package)
        ok_classes = 0
        for name, g in gen.items():
            total += 1
            issues = []
            a = app.get(name)
            if a is None:
                issues.append("class missing in abc_shop/" + package)
            else:
                fields, methods, params = members(a, app)
                gbases = [ast.unparse(b) for b in g.bases if ast.unparse(b) not in ("ABC",)]
                abases = [ast.unparse(b).split(".")[-1] for b in a.bases]
                for b in gbases:
                    if b not in abases:
                        issues.append(f"superclass {b} missing")
                for st in g.body:
                    if isinstance(st, ast.FunctionDef) and st.name == "__init__":
                        for node in ast.walk(st):
                            if isinstance(node, ast.Attribute) and isinstance(node.value, ast.Name) \
                                    and node.value.id == "self":
                                field = node.attr.lstrip("_")
                                if field not in fields:
                                    issues.append(f"attribute {field} missing")
                    elif isinstance(st, ast.FunctionDef):
                        if st.name not in methods:
                            issues.append(f"operation {st.name} missing")
                        else:
                            want = [x.arg for x in st.args.args if x.arg not in ("self", "cls")]
                            have = params.get(st.name, [])
                            if want != have:
                                issues.append(f"operation {st.name}{tuple(want)} has parameters {tuple(have)}")
            if issues:
                problems += 1
                lines.append(f"  {package}.{name}: " + "; ".join(issues))
            else:
                ok_classes += 1
        lines.insert(len(lines), f"[{package}] {len(gen)} generated classes, {ok_classes} match abc_shop/{package}")
    print("Code generated by generateCode (design/generated) compared with the application (abc_shop)")
    print("\n".join(lines))
    print(f"\nTotal: {total} classes, {total - problems} match in superclass, attributes and operations, "
          f"{problems} differ")
    return 1 if problems else 0


if __name__ == "__main__":
    sys.exit(main())
